a":{"ag_transition":true,"ag_component_change":false,"ag_screen_change":false,"ag_skeleton_disappear":true,"ag_abrupt":false,"ag_screen_not_fade":false,"ag_skeleton_not_fade":false,"ag_transition_min":{"param":"UX.COMPONENT_TRANSITION_MIN_MS","mas":50},"ag_transition_max":{"param":"UX.COMPONENT_TRANSITION_MAX_MS","mas":-100},"ag_screen_fade":{"param":"UX.SCREEN_FADE_MS","mas":0},"ag_skeleton_fade":{"param":"UX.SKELETON_FADE_MS","mas":1}},"esperado":true}]}},{"codigo":"S22AG-218-1","legacy_id":218,"relacionadas":[],"coberturas":[{"legacy_id":218,"estado_cobertura":"REEMPLAZADA","residual":"","diferencias":"Contrato técnico de servidor cubierto íntegramente en ámbito BACKEND."}],"paquete":{"tipo":"NUEVA","codigo":"S22AG-218-1","clave":"s22ag_legacy_218_0","familia":"API_DATA_CONTRACT","naturaleza":"CONDUCTA","clase":"BACKEND","alcance":"BACKEND","modo":"HEREDA","dueno":"TECNICO","titulo":"CORS configurado explícitamente","descripcion":"BLOQUEAR incumplimiento: CORS solo permite orígenes autorizados: dominio de producción de LF, dominio de staging. No usar wildcard (*) en producción. Métodos permitidos: GET, POST, PATCH. Headers permitidos: Content-Type, Authorization, X-Idempotency-Key. Referencias literales del contrato fuente: {\"headers\":[\"Content-Type\",\"Authorization\",\"X-Idempotency-Key\"],\"metodos\":[\"GET\",\"POST\",\"PATCH\"],\"origenes_permitidos\":[\"dominio_produccion_lf\",\"dominio_staging\"],\"no_wildcard_produccion\":true}. Binding runtime pendiente.","efecto":"BLOQUEAR","autoridad":"LEG-TECNICO","impacto":"REVISAR","origen":{"tipo":"MIGRACION","ref":"lf_ops.reglas/218","solicitante":"Cristhian / Claude S22-AG"},"condicion":{"op":"y","izq":{"op":"=","izq":{"hecho":"ag_cors"},"der":{"lit":true}},"der":{"op":"o","izq":{"op":"o","izq":{"op":"o","izq":{"op":"=","izq":{"hecho":"ag_origin_unauthorized"},"der":{"lit":true}},"der":{"op":"=","izq":{"hecho":"ag_prod_wildcard"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ag_method_unauthorized"},"der":{"lit":true}}},"der":{"op":"=","izq":{"hecho":"ag_header_unauthorized"},"der":{"lit":true}}}},"pruebas":[{"casuistica":"NO_SE_CUMPLE","entrada":{"ag_cors":true,"ag_origin_unauthorized":false,"ag_prod_wildcard":false,"ag_method_unauthorized":false,"ag_header_unauthorized":false},"esperado":false},{"casuistica":"SE_CUMPLE","entrada":{"ag_cors":true,"ag_origin_unauthorized":true,"ag_prod_wildcard":false,"ag_method_unauthorized":false,"ag_header_unauthorized":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"ag_cors":true,"ag_origin_unauthorized":false,"ag_prod_wildcard":true,"ag_method_unauthorized":false,"ag_header_unauthorized":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"ag_cors":true,"ag_origin_unauthorized":false,"ag_prod_wildcard":false,"ag_method_unauthorized":true,"ag_header_unauthorized":false},"esperado":true},{"casuistica":"SE_CUMPLE","entrada":{"ag_cors":true,"ag_origin_unauthorized":false,"ag_prod_wildcard":false,"ag_method_unauthorized":false,"ag_header_unauthorized":true},"esperado":true},{"casuistica":"NO_SE_CUMPLE","entrada":{"ag_cors":false,"ag_origin_unauthorized":true,"ag_prod_wildcard":true,"ag_method_unauthorized":true,"ag_header_unauthorized":true},"esperado":false}]}}]$pack$::jsonb; p jsonb; a jsonb; ans jsonb; cd text; h text; hashes jsonb:='{}'; hash_all text; t record;
BEGIN
 FOR p IN SELECT value FROM jsonb_array_elements(packs) LOOP
 a:=p->'paquete'; cd:=p->>'codigo';
 IF EXISTS(WITH RECURSIVE anc AS (SELECT codigo,padre FROM lf_ops.nucleo_nodos WHERE pantalla_id=36 UNION ALL SELECT nn.codigo,nn.padre FROM lf_ops.nucleo_nodos nn JOIN anc z ON nn.codigo=z.padre) SELECT 1 FROM anc WHERE codigo=a->>'alcance') THEN RAISE EXCEPTION 'S22_SCOPE_P36 %',cd; END IF;
 ans:=lf_ops.nucleo_regla_proponer_v1(a,true);
 IF ans->>'resultado' IS DISTINCT FROM 'CANDIDATA' OR (ans->>'version')::int IS DISTINCT FROM 1 THEN RAISE EXCEPTION 'S22AG_PROPOSAL_FAIL % %',cd,ans; END IF;
 ans:=lf_ops.nucleo_regla_evaluar_v1(cd,true);
 h:=lf_ops.nucleo_hash_paquete_v1(cd,1); hashes:=hashes||jsonb_build_object(cd,h);
 FOR t IN SELECT entrada,esperado FROM lf_ops.nucleo_regla_pruebas WHERE regla=cd AND version=1 LOOP
 IF lf_ops.nucleo_eval_v1(a->'condicion',t.entrada) IS DISTINCT FROM t.esperado THEN RAISE EXCEPTION 'S22AG_VECTOR_FAIL %',cd; END IF; END LOOP;
 END LOOP;
 SELECT string_agg(j.key||'='||j.value,',' ORDER BY j.key) INTO hash_all FROM jsonb_each_text(hashes) j;
 RAISE EXCEPTION 'S22AG_HASH_ALL %',hash_all;
END $ag$;
COMMIT;
